result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/terrain_dijkstra.py", "content": """"Weighted-terrain Dijkstra over a digit grid.

Semantics: moving into cell (r, c) costs int(grid[r][c]). The start cell
itself costs nothing. Movement is 4-connected. Returns (total_cost, path).
"""

import heapq

DIRS = ((-1, 0), (1, 0), (0, -1), (0, 1))


def dijkstra(grid, start, goal):
    """Cheapest 4-connected path on `grid` (list of strings / digit chars).

    Entering a cell costs its digit. Start cell is free.
    Returns (cost, path) where path is a list of (r, c) tuples inclusive
    of both endpoints, or raises ValueError if unreachable.
    """
    if not grid or not grid[0]:
        raise ValueError("empty grid")
    rows, cols = len(grid), len(grid[0])
    start, goal = tuple(start), tuple(goal)
    for r, c in (start, goal):
        if not (0 <= r < rows and 0 <= c < cols):
            raise ValueError(f"endpoint {(r, c)} outside grid")

    cost_of = lambda p: int(grid[p[0]][p[1]])
    dist = {start: 0}
    prev = {start: None}
    heap = [(0, start)]
    while heap:
        d, u = heapq.heappop(heap)
        if d > dist.get(u, float("inf")):
            continue
        if u == goal:
            break
        r, c = u
        for dr, dc in DIRS:
            v = (r + dr, c + dc)
            if not (0 <= v[0] < rows and 0 <= v[1] < cols):
                continue
            nd = d + cost_of(v)
            if nd < dist.get(v, float("inf")):
                dist[v] = nd
                prev[v] = u
                heapq.heappush(heap, (nd, v))

    if goal not in prev:
        raise ValueError("goal unreachable")

    path, node = [], goal
    while node is not None:
        path.append(node)
        node = prev[node]
    path.reverse()
    return dist[goal], path


def bfs_distance(rows, cols, start, goal):
    """Unweighted 4-connected shortest-path length in moves (for tests)."""
    from collections import deque

    start, goal = tuple(start), tuple(goal)
    q, seen = deque([start]), {start: 0}
    while q:
        u = q.popleft()
        if u == goal:
            return seen[u]
        r, c = u
        for dr, dc in DIRS:
            v = (r + dr, c + dc)
            if 0 <= v[0] < rows and 0 <= v[1] < cols and v not in seen:
                seen[v] = seen[u] + 1
                q.append(v)
    return None


def path_cost(grid, path):
    """Independent recompute: sum of entry digits along a path."""
    return sum(int(grid[r][c]) for r, c in path[1:])
